{
  "segment_function": "Introduction of Chapter II, discussing the relation between the vita activa and human togetherness, and examining the translation and historical evolution of animal socialis versus zōon politikon.",
  "claims": [
    {
      "claim": "All human activities are conditioned by human togetherness, but only action exclusively depends upon the constant presence of others.",
      "claim_type": "author_position",
      "supporting_excerpt": "All human activities are conditioned by the fact that men live together, but it is only action that cannot even be imagined outside the society of men.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "The translation of Aristotle's zōon politikon as animal socialis reflects a loss of the original Greek understanding of politics.",
      "claim_type": "author_position",
      "supporting_excerpt": "More than any elaborate theory, this unconscious substitution of the social for the political betrays the extent to which the original Greek understanding of politics had been lost.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "vita activa",
      "definition": "Human life in so far as it is actively engaged in doing something, always rooted in a world of men and man-made things."
    }
  ],
  "distinctions": [
    {
      "item_a": "idion (what is one's own)",
      "item_b": "koinon (what is communal)",
      "distinction": "A sharp distinction in a citizen's life between private existence and communal existence corresponding to the household versus the city-state."
    }
  ]
}

